function evidence = f90_xbatt06_extract_candidate_evidence( ...
        modelPath, outputDir)
%F90_XBATT06_EXTRACT_CANDIDATE_EVIDENCE Replay the public 3RC/RUL contract.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot, sharedRoot] = localRoots("F90-XBATT-06");
addpath(sharedRoot, "-begin");
cleanup = onCleanup(@() rmpath(sharedRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.f90-xbatt06-evidence.v1", ...
    "task_id", "F90-XBATT-06", ...
    "task_root", taskRoot, ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localRequested, ...
    "stop_time", @localStopTime, ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "finalize_evidence", @localFinalizeEvidence, ...
    "evidence_sample_count", 2001, ...
    "evidence_sample_s", 1.0);
evidence = simuverity_run_candidate_evidence( ...
    modelPath, outputDir, spec);
end

function rows = localOutputs
rows = localRows(["electrical_state", "identified_3rc", "rul_state"], ...
    [4 8 4]);
end

function inputs = localInputs(scenario, spec)
data = localScenarioData(scenario, spec);
inputs = struct( ...
    "battery_input", timeseries( ...
        [data.current_A, data.temperature_K], data.time_s), ...
    "initial_soc", data.initial_soc, ...
    "available_capacity_Ah", data.available_capacity_Ah, ...
    "forecast_discharge_current_A", ...
        double(scenario.forecast_discharge_current_A), ...
    "reserve_capacity_Ah", double(scenario.reserve_capacity_Ah), ...
    "required_landing_time_s", ...
        double(scenario.required_landing_time_s));
end

function requested = localRequested(scenario, spec)
data = localScenarioData(scenario, spec);
requested = struct( ...
    "dataset_index", double(scenario.dataset_index), ...
    "dataset_file", string(scenario.dataset_file), ...
    "temperature_K", double(scenario.temperature_K), ...
    "initial_soc", data.initial_soc, ...
    "available_capacity_Ah", data.available_capacity_Ah, ...
    "initial_charge_deficit_Ah", data.initial_charge_deficit_Ah, ...
    "forecast_discharge_current_A", ...
        double(scenario.forecast_discharge_current_A), ...
    "reserve_capacity_Ah", double(scenario.reserve_capacity_Ah), ...
    "required_landing_time_s", ...
        double(scenario.required_landing_time_s));
end

function stopTime = localStopTime(scenario, spec)
data = localScenarioData(scenario, spec);
stopTime = data.time_s(end);
end

function row = localPostprocess(row, outputs, scenario, spec)
data = localScenarioData(scenario, spec);
t = double(outputs.time_s(:));
outputs.battery_input = [ ...
    interp1(data.time_s, data.current_A, t, "previous", "extrap"), ...
    double(scenario.temperature_K) .* ones(size(t))];
outputs.experimental_voltage_V = interp1( ...
    data.time_s, data.experimental_voltage_V, t, "linear", "extrap");
row.outputs = outputs;
allValues = [outputs.battery_input(:); ...
    outputs.experimental_voltage_V(:); outputs.electrical_state(:); ...
    outputs.identified_3rc(:); outputs.rul_state(:)];
row.metrics = struct( ...
    "sample_count", numel(t), ...
    "all_finite", all(isfinite(allValues)), ...
    "time_coverage_fraction", ...
        (t(end) - t(1)) / max(data.time_s(end), eps));
row.valid = row.output_contract.all_required_pass && ...
    numel(t) == 2001 && row.metrics.all_finite && ...
    t(1) <= 1e-9 && t(end) >= data.time_s(end) - 1e-6;
end

function audit = localAudit(model, spec)
names = string({spec.output_contract.name})';
structure = simuverity_candidate_structure(model, names);
usesBatteryInput = localUsesVariable(model, "battery_input");
allOutputs = structure.connected_output_count == numel(names) && ...
    structure.nontrivial_output_source_count == numel(names);
audit = struct( ...
    "current_input_connected_to_plant_and_estimator", usesBatteryInput, ...
    "temperature_input_connected", usesBatteryInput, ...
    "four_native_outputs_present", allOutputs, ...
    "identified_3rc_parameter_fields_present", ...
        allOutputs && any(names == "identified_3rc"), ...
    "dynamic_state_block_count", structure.dynamic_block_count, ...
    "connected_public_output_count", structure.connected_output_count, ...
    "nontrivial_public_output_source_count", ...
        structure.nontrivial_output_source_count, ...
    "core_path_qualified", usesBatteryInput && allOutputs && ...
        structure.dynamic_block_count >= 4);
end

function evidence = localFinalizeEvidence(evidence, ~)
evidence.evidence_complete = logical(evidence.score_inputs_valid);
end

function tf = localUsesVariable(model, variable)
tf = false;
try
    tf = ~isempty(Simulink.findVars(model, "Name", char(variable)));
catch
end
end

function data = localScenarioData(scenario, spec)
referenceRoot = fullfile(spec.task_root, "reference", "src");
parameters = load(fullfile(referenceRoot, ...
    "20230919_data_modelparams.mat"), "mp");
performance = load(fullfile(referenceRoot, ...
    "20230919_data_performance.mat"), "xhat");
index = double(scenario.dataset_index);
assert(index >= 1 && index <= numel(parameters.mp.fn), ...
    "SimuVerity:F90:XBATT06:DatasetIndex", "Invalid official dataset index.");
assert(strcmp(string(parameters.mp.fn(index)), ...
    string(scenario.dataset_file)), "SimuVerity:F90:XBATT06:DatasetIdentity", ...
    "Official dataset identity does not match the fixed scenario.");
payload = load(fullfile(referenceRoot, "data", ...
    char(scenario.dataset_file)), "i", "v", "t");
time = double(payload.t(:));
current = double(payload.i(:));
voltage = double(payload.v(:));
current(~isfinite(current)) = 0;
keep = isfinite(time) & isfinite(voltage);
time = time(keep); current = current(keep); voltage = voltage(keep);
time = time - time(1);
[time, uniqueIndex] = unique(time, "stable");
current = current(uniqueIndex); voltage = voltage(uniqueIndex);
assert(numel(time) >= 100 && time(end) > 100, ...
    "SimuVerity:F90:XBATT06:DatasetCoverage", ...
    "Official battery input does not cover a complete scenario.");
initialSoc = interp1(parameters.mp.Em, parameters.mp.SOC_LUT, ...
    max(voltage), "linear", "extrap");
initialSoc = min(1, max(0, initialSoc));
capacity = double(performance.xhat(index, 1));
deficit = double(performance.xhat(index, 2)) * ...
    (1 - initialSoc) * capacity;
data = struct( ...
    "time_s", time, ...
    "current_A", current, ...
    "temperature_K", double(scenario.temperature_K) .* ones(size(time)), ...
    "experimental_voltage_V", voltage, ...
    "initial_soc", initialSoc, ...
    "available_capacity_Ah", capacity, ...
    "initial_charge_deficit_Ah", deficit);
end

function rows = localRows(names, widths)
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for k = 1:numel(names)
    rows(k).name = names(k);
    rows(k).evidence_name = names(k);
    rows(k).width = widths(k);
end
end

function [taskRoot, sharedRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for k = 1:3, repoRoot = fileparts(repoRoot); end
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end
